3	import (
4		"os"
5		"strings"
6		"testing"
7	)
8	
9	func TestActivityFilterClauseMatchesWorkflowNamesAndUUIDs(t *testing.T) {
10		featureID := "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"
11		taskID := "dddddddd-dddd-dddd-dddd-dddddddddddd"
12		clause, args, nextArg, err := activityFilterClause(featureID, taskID, 2)
13		if err != nil {
14			t.Fatalf("unexpected error: %v", err)
15		}
16	
17		if nextArg != 4 {
18			t.Fatalf("expected next arg position 4, got %d", nextArg)
19		}
20		if len(args) != 2 {
21			t.Fatalf("unexpected args: %#v", args)
22		}
23	
24		for _, want := range []string{
25			"feature_id = $2",
26			"task_id = $3",
27		} {
28			if !strings.Contains(clause, want) {
29				t.Fatalf("expected activity filter clause to contain %q, got %q", want, clause)
30			}
31		}
32		for _, forbidden := range []string{"feature_id::text", "task_id::text", "feature_name", "task_name"} {
33			if strings.Contains(clause, forbidden) {
34				t.Fatalf("activity filter must not match %q in ID filters, got %q", forbidden, clause)
35			}
36		}
37	}
38	
39	func TestListActivityEventsUsesIndependentActivityFilterClause(t *testing.T) {
40		source, err := os.ReadFile("queries.go")
41		if err != nil {
42			t.Fatalf("read queries.go: %v", err)
43		}
44	
45		body := string(source)
46		start := strings.Index(body, "func (r *Reader) ListActivityEvents")
47		if start < 0 {
48			t.Fatal("ListActivityEvents not found")
49		}
50		end := strings.Index(body[start:], "// UUIDString converts")
51		if end < 0 {
52			t.Fatal("ListActivityEvents end marker not found")
53		}
54		listActivityEvents := body[start : start+end]
55	
56		if !strings.Contains(listActivityEvents, "activityFilterClause(featureID, taskID, 2)") {
57			t.Fatalf("ListActivityEvents must build feature and task filters independently with activityFilterClause")
58		}
59	}
60	
61	func TestTaskIDOrderAscUsesNumericWorkflowOrder(t *testing.T) {
62		clause := taskIDOrderAsc("t")
63	
64		for _, want := range []string{
65			"regexp_replace(t.task_name, '^T([0-9]+)$', '\\1')",
66			"::int ASC",
67			"t.task_name ASC",
68		} {
69			if !strings.Contains(clause, want) {
70				t.Fatalf("expected task order clause to contain %q, got %q", want, clause)
71			}
72		}
73		if strings.Contains(clause, "regexp_replace(t.task_id") {
74			t.Fatalf("task order must not call regexp_replace on UUID task_id, got %q", clause)
75		}
76	}
77	
78	func TestQueryLayerDoesNotResolveReferencesByNames(t *testing.T) {
79		// UUID validation is implicit: invalid UUIDs return ErrNotFound directly via parseUUID;
80		// missing rows return ErrNotFound via pgx.ErrNoRows in the main query.
81		// The query layer must never resolve by mutable name columns.
82		forbidden := []string{
83			"WHERE workspace_id = $1 AND feature_name = $2",
84			"WHERE workspace_id = $1 AND feature_id = $2 AND task_name = $3",
85			"SELECT id FROM workspace_features WHERE workspace_id = $1 AND feature_id = $2",
86			"SELECT id FROM workspace_tasks WHERE workspace_id = $1 AND feature_id = $2 AND task_id = $3",
87			// ensure the old existence-check round-trips are gone
88			"SELECT feature_id FROM workspace_features WHERE workspace_id = $1 AND feature_id = $2",
89			"SELECT task_id FROM workspace_tasks WHERE workspace_id = $1 AND feature_id = $2 AND task_id = $3",
90		}
91	
92		source := queriesSourceForContractTest()
93		for _, fragment := range forbidden {
94			if strings.Contains(source, fragment) {
95				t.Fatalf("query layer must resolve references by public UUID columns only; found %q", fragment)
96			}
97		}
98	}
99	
100	func queriesSourceForContractTest() string {
101		data, err := os.ReadFile("queries.go")
102		if err != nil {
103			panic(err)
104		}
105		return string(data)
106	}
107

